const version = $('Receber Solicitação').first().json.body.version || "0.0.0";
const tasks = $input.first().json.tasks || [];

const formatted = tasks
  .filter(function(task) {
    const rnField = (task.custom_fields || []).find(function(f) {
      return f.id === 'ac9cc1c0-5d4b-4f4c-8f53-036f2fd03d51';
    });
    return rnField && (rnField.value === true || rnField.value === 1 || rnField.value === 'true');
  })
  .map(function(task) {
    const fields = task.custom_fields || [];
    const getField = function(id) { return fields.find(function(f) { return f.id === id; }); };

    const textoRN = getField('13aca943-0a8f-461b-8232-bf349a30d9ae')
      ? getField('13aca943-0a8f-461b-8232-bf349a30d9ae').value || '' : '';

    const classificacao = getField('67168419-6e82-4550-a5d3-f412fb879183');
    const modulo = getField('d680dce5-81ff-45e4-99d5-1cc2ea4cc36b');
    const plataforma = getField('3c265030-b3d6-497a-87b2-d060ef6a9c31');

    const classificacaoNome = classificacao && classificacao.type_config &&
      classificacao.type_config.options && classificacao.value !== undefined
      ? (classificacao.type_config.options[classificacao.value]
        ? classificacao.type_config.options[classificacao.value].name : '') : '';

    const moduloNome = modulo && modulo.type_config &&
      modulo.type_config.options && modulo.value !== undefined
      ? (modulo.type_config.options[modulo.value]
        ? modulo.type_config.options[modulo.value].name : '') : '';

    const plataformaNome = plataforma && plataforma.type_config &&
      plataforma.type_config.options && plataforma.value !== undefined
      ? (plataforma.type_config.options[plataforma.value]
        ? plataforma.type_config.options[plataforma.value].name : '') : '';

    return {
      id: task.id,
      titulo: task.name,
      classificacao: classificacaoNome,
      modulo: moduloNome,
      plataforma: plataformaNome,
      texto_rn: textoRN,
      descricao: task.text_content || '',
      tags: task.tags || []
    };
  });

const aviso = 'NOTA: As funcionalidades apresentadas neste release notes podem variar de acordo com a licen\u00e7a contratada pela sua institui\u00e7\u00e3o. Em caso de d\u00favidas sobre disponibilidade, nossa equipe estar\u00e1 \u00e0 disposi\u00e7\u00e3o para ajudar. Caso deseje atualizar sua vers\u00e3o, entre em contato com nosso canal de suporte.';

const prompt = 'Voce e um redator tecnico especialista em release notes de software medico.\n\nAbaixo estao as tarefas concluidas na versao ' + version + ' do sistema Naja.\nGere um release notes profissional, claro e bem estruturado em portugues brasileiro.\n\nEstrutura OBRIGATORIA do release notes:\n\n# Release Notes | ' + version + '\n**Data de lancamento:** \n\nPara cada modulo que tiver tarefas, use a estrutura:\n\n## NOME DO MODULO\n\n### Melhorias\n- (lista de melhorias e novas funcionalidades)\n\n### Correcoes\n- (lista de bugs corrigidos)\n\nRegras:\n- Agrupe SEMPRE por Modulo\n- Dentro de cada modulo, SEMPRE separe em Melhorias e Correcoes\n- Classificacao BUG vai em Correcoes, todo o resto vai em Melhorias\n- Se um modulo nao tiver melhorias ou nao tiver correcoes, omita a subsecao vazia\n- Use linguagem voltada ao usuario final, nao tecnica\n- Seja objetivo mas completo\n- Se o campo texto_rn estiver preenchido, use-o como base. Se nao, use o titulo e a descricao.\n- Deixe o campo Data de lan\u00e7amento vazio para preenchimento manual\n- Ao final inclua EXATAMENTE este texto: ' + aviso + '\n\nTarefas:\n' + JSON.stringify(formatted, null, 2) + '\n\nGere o release notes agora:';

const bodyString = JSON.stringify({
  model: 'claude-haiku-4-5',
  max_tokens: 2000,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { bodyString: bodyString, tasks: formatted, version: version } }];

const response = items[0].json;
const releaseNotesText = response.content[0].text;
const version = $('Receber Solicitação').first().json.body.version || "0.0.0";
const tasks = $('Formatar Dados e Prompt').first().json.tasks || [];

return [{
  json: {
    version,
    title: `Release Notes ${version}`,
    content: releaseNotesText,
    published_at: new Date().toISOString(),
    tasks
  }
}];
